CREATE TABLE quizzes (id BIGINT PRIMARY KEY AUTO_INCREMENT, owner_id BIGINT NOT NULL, material_id BIGINT NOT NULL, title VARCHAR(255) NOT NULL, questions_json TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_quiz_owner FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_quiz_material FOREIGN KEY(material_id) REFERENCES materials(id) ON DELETE CASCADE, INDEX idx_quiz_owner(owner_id));
CREATE TABLE quiz_attempts (id BIGINT PRIMARY KEY AUTO_INCREMENT, quiz_id BIGINT NOT NULL, student_id BIGINT NOT NULL, score INT NOT NULL, total_questions INT NOT NULL, answers_json TEXT NOT NULL, submitted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_attempt_quiz FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE, CONSTRAINT fk_attempt_student FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_attempt_student(student_id,submitted_at));
